const pollableSimulations = `-- name: PollableSimulations :many
SELECT run_id, campaign_id, simulator, executor, state, steps, completed_steps, job_id, job_queue, job_definition, artifact_uri, reservation_usd_micros, timeout_seconds, reason, log_stream, log_token, inspection_error, cancellation_requested, cleanup_confirmed, created_at, updated_at, managed, capture_every, artifact_volume, trace_url, trace_export_error, trace_retry_at, log_document_id, log_projection_error, log_indexed_at, log_retry_at FROM brainspine_simulations WHERE executor = 2 AND job_id <> ''
AND (state IN ('queued','running','cancelling') OR (state IN ('succeeded','failed','cancelled') AND updated_at > now() - interval '10 minutes'))
ORDER BY updated_at, run_id LIMIT 32
`

func (q *Queries) PollableSimulations(ctx context.Context) ([]BrainspineSimulation, error) {
	rows, err := q.db.Query(ctx, pollableSimulations)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []BrainspineSimulation{}
	for rows.Next() {
		var i BrainspineSimulation
		if err := rows.Scan(
			&i.RunID,
			&i.CampaignID,
			&i.Simulator,
			&i.Executor,
			&i.State,
			&i.Steps,
			&i.CompletedSteps,
			&i.JobID,
			&i.JobQueue,
			&i.JobDefinition,
			&i.ArtifactUri,
			&i.ReservationUsdMicros,
			&i.TimeoutSeconds,
			&i.Reason,
			&i.LogStream,
			&i.LogToken,
			&i.InspectionError,
			&i.CancellationRequested,
			&i.CleanupConfirmed,
			&i.CreatedAt,
			&i.UpdatedAt,
			&i.Managed,
			&i.CaptureEvery,
			&i.ArtifactVolume,
			&i.TraceUrl,
			&i.TraceExportError,
			&i.TraceRetryAt,
			&i.LogDocumentID,
			&i.LogProjectionError,
			&i.LogIndexedAt,
			&i.LogRetryAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

